<script setup>
import {ref,onMounted} from 'vue'
import {api} from './api'
const props=defineProps({token:String,language:String})
const emit=defineEmits(['dirty'])
const tr=(ru,uz,en)=>props.language==='uz'?uz:props.language==='en'?en:ru
const data=ref(null),gate=ref(null),busy=ref(false),error=ref(''),notice=ref(''),chosen=ref(null),confirmation=ref(''),finishConfirmation=ref(''),after=ref('')
const request=(path,body)=>api(path,{token:props.token,...(body?{method:'POST',body:JSON.stringify(body)}:{})})
async function load(){data.value=await request('/api/owner/wallet/vip-import?'+new URLSearchParams({after:after.value}));gate.value=data.value.enabled?await request('/api/owner/wallet/vip-migration'):null;emit('dirty',false)}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
function choose(card){chosen.value=card;confirmation.value='';emit('dirty',false)}
async function migrate(){await request('/api/owner/wallet/vip-import',{uid:chosen.value.uid,confirmation:confirmation.value});chosen.value=null;confirmation.value='';await load();notice.value=tr('VIP перенесён. Дневные допуски сохранены.','VIP ko‘chirildi. Kunlik foydalanish saqlandi.','VIP imported. Daily usage preserved.')}
async function finish(){await request('/api/owner/wallet/vip-migration/complete',{confirmation:finishConfirmation.value});finishConfirmation.value='';await load();notice.value=tr('Перенос VIP всей мойки подтверждён.','Yuvishdagi barcha VIP ko‘chirilgani tasdiqlandi.','Site VIP migration confirmed.')}
const count=c=>Object.values(c.daily_uses||{}).reduce((n,v)=>n+Number(v),0)
const status=s=>s==='active'?tr('Активна','Faol','Active'):s==='blocked'?tr('Заблокирована','Bloklangan','Blocked'):s==='lost'?tr('Утеряна','Yo‘qolgan','Lost'):tr('Истекла','Muddati tugagan','Expired')
onMounted(()=>run(load))
</script>
<template>
<section class="card content vip-migration">
<h2>{{tr('Перенос локальных VIP','Mahalliy VIP ko‘chirish','Import local VIP')}}</h2>
<p>{{tr('Переносятся профиль, статус, использованные дневные допуски и сохранённый VIP-остаток. Деньги не создаются. Перенесите источники на всех постах, затем подтвердите завершение на главном.','Profil, holat, kunlik foydalanish va saqlangan VIP qoldiq ko‘chiriladi. Pul yaratilmaydi. Barcha postlarda manbalarni ko‘chiring, keyin asosiy postda yakunlang.','Profiles, status, daily usage and preserved VIP allowance are imported. No money is created. Import sources on every station, then complete migration on the primary.')}}</p>
<p class="muted">{{tr('При конфликте сверите общий профиль или карту на главном. Повтор после потери ответа безопасен.','Ziddiyat bo‘lsa, asosiy postdagi umumiy profil yoki kartani tekshiring. Javob yo‘qolganda qayta urinish xavfsiz.','Reconcile conflicting profiles or card metadata on the primary. Retrying after a lost response is safe.')}}</p>
<p v-if="error" role="alert" class="message error">{{error}}</p><p v-if="notice" role="status" class="message success">{{notice}}</p><p v-if="busy" role="status">{{tr('Проверка…','Tekshirilmoqda…','Checking…')}}</p>
<button class="quiet" :disabled="busy||!!confirmation||!!finishConfirmation" @click="run(load)">{{tr('Обновить','Yangilash','Refresh')}}</button>
<template v-if="data"><p v-if="!data.enabled" class="message">{{tr('При установке кошелька включите сохранение локальных VIP. Затем сюда появятся замороженные источники.','Hamyonga o‘tishda mahalliy VIP saqlashni yoqing. Muzlatilgan manbalar shu yerda chiqadi.','Preserve local VIP during wallet setup. Frozen sources will appear here.')}} · {{data.unstaged}}</p>
<div class="table-wrap"><table><thead><tr><th>UID</th><th>{{tr('Карта / профиль','Karta / profil','Card / profile')}}</th><th>{{tr('Использовано','Ishlatilgan','Used')}}</th><th>{{tr('VIP-остаток','VIP qoldiq','VIP allowance')}}</th><th>{{tr('Статус','Holat','Status')}}</th><th></th></tr></thead><tbody><tr v-for="c in data.cards" :key="c.uid"><th>{{c.uid}}</th><td>{{c.display_name||'—'}}<small class="muted">{{c.profile.code}} · {{c.profile.name}}</small></td><td>{{count(c)}}<small v-for="(value,day) in c.daily_uses">{{day}}: {{value}}</small></td><td>{{Number(c.visit?.remaining_sum||0).toLocaleString('ru-RU')}}<small>{{tr('Виртуальные сум, не деньги','Virtual so‘m, pul emas','Virtual sum, no cash')}}</small></td><td>{{status(c.status)}}{{c.enabled?'':' · OFF'}}<small>{{c.import_status==='done'?tr('Перенесено','Ko‘chirildi','Imported'):tr('Ожидает переноса','Ko‘chirish kutilmoqda','Pending import')}}</small></td><td><button class="quiet" :disabled="busy||!data.enabled||c.import_status==='done'||!!confirmation||!!finishConfirmation" @click="choose(c)">{{tr('Перенести / повторить','Ko‘chirish / qaytarish','Import / retry')}}</button></td></tr></tbody></table></div>
<p v-if="!data.cards.length" class="muted">{{tr('На этом посту нет подготовленных локальных VIP.','Bu postda tayyorlangan mahalliy VIP yo‘q.','No staged local VIP on this station.')}}</p>
<div class="actions"><button class="quiet" :disabled="busy||!after||!!confirmation||!!finishConfirmation" @click="after='';run(load)">{{tr('Начало','Boshiga','First page')}}</button><button class="quiet" :disabled="busy||!data.next_after||!!confirmation||!!finishConfirmation" @click="after=data.next_after;run(load)">{{tr('Далее','Keyingi','Next')}}</button></div>
<form v-if="chosen" class="fields" @submit.prevent="run(migrate)"><label>{{tr('Введите для подтверждения','Tasdiqlash uchun kiriting','Type to confirm')}}: IMPORT VIP {{chosen.uid}}<input v-model="confirmation" autocomplete="off" @input="emit('dirty',true)"/></label><div class="actions"><button class="primary" :disabled="busy||confirmation!==`IMPORT VIP ${chosen.uid}`">{{tr('Подтвердить перенос VIP','VIP ko‘chirishni tasdiqlash','Confirm VIP import')}}</button><button class="quiet" type="button" :disabled="busy" @click="chosen=null;confirmation='';emit('dirty',false)">{{tr('Отмена','Bekor qilish','Cancel')}}</button></div></form>
<section v-if="gate" class="completion"><h3>{{tr('Завершение по всем постам','Barcha postlarda yakunlash','Complete all stations')}}</h3><p>{{gate.complete?tr('Перенос VIP подтверждён.','VIP ko‘chirish tasdiqlangan.','VIP migration confirmed.'):tr('Выдача VIP ждёт сверки всех известных постов.','VIP berish barcha ma’lum postlarni tekshirishni kutmoqda.','VIP grants await reconciliation of all known stations.')}}</p><p class="muted">{{tr('В список мойки должны входить все её посты. При завершении проверяются подключение и отсутствие незавершённых источников на каждом.','Yuvish ro‘yxatida uning barcha postlari bo‘lishi kerak. Yakunlashda har bir post ulanishi va tugallanmagan manbalar tekshiriladi.','The site registry must include every station. Completion checks connectivity and unfinished sources at each station.')}}</p>
<form v-if="gate.can_finish&&!gate.complete" class="fields" @submit.prevent="run(finish)"><label>{{tr('Введите','Kiriting','Type')}} COMPLETE VIP MIGRATION SITE {{gate.site_id}}<input v-model="finishConfirmation" autocomplete="off" @input="emit('dirty',true)"/></label><button class="primary" :disabled="busy||finishConfirmation!==`COMPLETE VIP MIGRATION SITE ${gate.site_id}`">{{tr('Завершить перенос VIP','VIP ko‘chirishni yakunlash','Complete VIP migration')}}</button></form><p v-else-if="!gate.can_finish" class="muted">{{tr('Завершение подтверждает Owner на главном посту.','Owner yakunlashni asosiy postda tasdiqlaydi.','Owner completes migration on the primary station.')}}</p></section>
</template></section>
</template>
<style scoped>
.vip-migration{padding:28px 30px}.vip-migration>p{line-height:1.6;margin:18px 0}.vip-migration small{display:block;margin-top:6px}.vip-migration .fields{padding:20px 0}.completion{border-top:1px solid var(--border);padding-top:24px;margin-top:24px}.completion p{line-height:1.6}.vip-migration .actions{margin:18px 0}@media(max-width:650px){.vip-migration{padding:20px}}
</style>
